/**
 * Snapshot the Python evaluator into a TypeScript module the app can import.
 *
 * Staging's server build ignores custom rsbuild loaders and cannot resolve
 * files outside the app folder, so the flat RestrictedPython-safe script that
 * `tool_python` executes is generated here (by tools/build_restricted_bundle.py)
 * and committed as a string constant.
 *
 * Source of truth for the algorithm remains the Python files under
 * Projects/hackathon-usage-verifier/eval. Re-run this script after editing
 * them. Do not edit the generated module by hand. Requires a local Python 3.9+.
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const appRoot = path.resolve(here, '..');
const outFile = path.join(appRoot, 'src', 'verify', 'generated', 'evaluatorBundle.ts');
const builder = path.join(here, 'build_restricted_bundle.py');

function runPython() {
	const candidates = process.platform === 'win32' ? ['python', 'py', 'python3'] : ['python3', 'python'];
	let lastError = '';
	for (const bin of candidates) {
		const args = bin === 'py' ? ['-3', builder] : [builder];
		const proc = spawnSync(bin, args, {
			encoding: 'utf8',
			maxBuffer: 64 * 1024 * 1024,
			env: { ...process.env, PYTHONIOENCODING: 'utf-8', PYTHONUTF8: '1' },
		});
		if (proc.error) {
			lastError = proc.error.message;
			continue;
		}
		if (proc.status !== 0) {
			throw new Error(`${bin} ${builder} failed (${proc.status}):\n${proc.stderr}`);
		}
		return proc.stdout;
	}
	throw new Error(`No Python interpreter found to build the evaluator bundle (${lastError})`);
}

// Windows text-mode stdout emits CRLF; the script must be byte-identical across hosts.
const bundle = runPython().replace(/\r\n?/g, '\n');
if (!/def run_verify\(/.test(bundle) || !/def run_extract\(/.test(bundle)) {
	throw new Error('Restricted bundle is missing its drivers (run_verify / run_extract)');
}
if (/^\s*nonlocal\b/m.test(bundle) || /\.format\(/.test(bundle)) {
	throw new Error('Restricted bundle still contains a construct RestrictedPython rejects');
}

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(
	outFile,
	[
		'/* Generated by tools/gen-evaluator-bundle.mjs — do not edit. */',
		'/** Flat RestrictedPython-safe evaluator (target + fetch shim + engine + extract + drivers). */',
		`export const RESTRICTED_BUNDLE: string = ${JSON.stringify(bundle)};`,
		'',
	].join('\n'),
	'utf8',
);

const bytes = fs.statSync(outFile).size;
console.log(`Wrote ${outFile} (${bundle.split('\n').length} lines, ${bytes} bytes)`);
